package com.example.billing.api;import static com.example.billing.api.Contracts.*;import com.example.billing.service.*;import java.net.URI;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController public class InvoiceController{private final InvoiceService invoices;private final PaymentService payments;public InvoiceController(InvoiceService i,PaymentService p){invoices=i;payments=p;}@PostMapping("/invoices/generate")ResponseEntity<?> generate(@RequestBody GenerateInvoiceRequest r){var x=invoices.generate(r.subscriptionId());if(x.invoice()==null)return ResponseEntity.badRequest().body(new ApiError(x.errorCode(),x.errorMessage()));var body=InvoiceResponse.from(x.invoice());return x.outcome()==InvoiceService.Outcome.CREATED?ResponseEntity.created(URI.create("/invoices/"+x.invoice().id)).body(body):ResponseEntity.ok(body);}@GetMapping("/invoices/{id}")ResponseEntity<?> get(@PathVariable UUID id){var x=invoices.get(id);return x==null?CatalogController.notFound("invoice_not_found","Invoice does not exist."):ResponseEntity.ok(InvoiceResponse.from(x));}@GetMapping("/customers/{id}/invoices")List<InvoiceResponse> list(@PathVariable UUID id){return invoices.list(id).stream().map(InvoiceResponse::from).toList();}@PostMapping("/invoices/{id}/pay")ResponseEntity<?> pay(@PathVariable UUID id,@RequestBody(required=false)PayInvoiceRequest request,@RequestHeader(value="Idempotency-Key",required=false)String key){if(key==null||key.isBlank())return ResponseEntity.badRequest().body(new ApiError("idempotency_key_required","Payment requests require an Idempotency-Key header."));if(request==null)request=new PayInvoiceRequest(null,false);var r=payments.pay(id,request,key.trim());if(r.outcome()==PaymentService.Outcome.CREATED)return ResponseEntity.created(URI.create("/payments/"+r.payment().id)).body(PaymentResponse.from(r.payment()));if(r.outcome()==PaymentService.Outcome.EXISTING)return ResponseEntity.ok(PaymentResponse.from(r.payment()));return ResponseEntity.status(r.statusCode()).body(new ApiError(r.errorCode(),r.errorMessage()));}}
